fn timed_lines(event: &CaldavIcalEvent) -> String {
    let start = DateTime::from_timestamp(event.start_utc, 0).unwrap_or(DateTime::UNIX_EPOCH);
    let end = DateTime::from_timestamp(event.end_utc, 0).unwrap_or(DateTime::UNIX_EPOCH);
    if !event.timezone.trim().is_empty()
        && !event.timezone.eq_ignore_ascii_case("utc")
        && let Ok(tz) = Tz::from_str(&event.timezone)
    {
        let start_local = tz.from_utc_datetime(&start.naive_utc());
        let end_local = tz.from_utc_datetime(&end.naive_utc());
        return format!(
            "DTSTART;TZID={}:{}\r\nDTEND;TZID={}:{}\r\n",
            event.timezone,
            start_local.format("%Y%m%dT%H%M%S"),
            event.timezone,
            end_local.format("%Y%m%dT%H%M%S")
        );
    }
    format!(
        "DTSTART:{}Z\r\nDTEND:{}Z\r\n",
        start.format("%Y%m%dT%H%M%S"),
        end.format("%Y%m%dT%H%M%S")
    )
}

