input.newString:
/// Event IDs currently exposed by this slice: timed and all-day,
/// non-recurring events that still exist in the calendar. Callers ensure a
/// stable resource mapping for each before serializing.
pub async fn list_exposed_event_ids(
    &self,
    calendar_id: i64,
) -> Result<Vec<i64>, CaldavAuthError> {
    let ids: Vec<i64> = sqlx::query_scalar(
        "SELECT id FROM events
          WHERE calendar_id = ?
            AND event_kind IN ('timed', 'all_day')
            AND recurrence_rule IS NULL
          ORDER BY id",
    )
    .bind(calendar_id)
    .fetch_all(&self.pool)
    .await
    .map_err(|_| CaldavAuthError::Persistence)?;
    Ok(ids)
}

/// Event IDs that overlap the given UTC time range, bounded by `limit`.
///
/// Timed events are matched against their UTC instants; all-day events are
/// matched against their calendar dates (the range endpoints are converted
/// to UTC dates), so a query window that touches a day includes the
/// all-day events spanning that day.
pub async fn list_events_in_range(
    &self,
    calendar_id: i64,
    start_utc: i64,
    end_utc: i64,
    limit: usize,
) -> Result<Vec<i64>, CaldavAuthError> {
    let start_date = utc_date(start_utc);
    let end_date = utc_date(end_utc);
    let ids: Vec<i64> = sqlx::query_scalar(
        "SELECT id FROM events
          WHERE calendar_id = ?
            AND recurrence_rule IS NULL
            AND (
                 (
                     event_kind = 'timed'
                     AND timed_start_utc < ?
                     AND timed_end_utc > ?
                 )
                 OR
                 (
                     event_kind = 'all_day'
                     AND all_day_start_date < ?
                     AND all_day_end_date > ?
                 )
            )
          ORDER BY id
          LIMIT ?",
    )
    .bind(calendar_id)
    .bind(end_utc)
    .bind(start_utc)
    .bind(end_date)
    .bind(start_date)
    .bind(limit as i64)
    .fetch_all(&self.pool)
    .await
    .map_err(|_| CaldavAuthError::Persistence)?;
    Ok(ids)
}

